#!/usr/bin/env bash
# Install the built .deb in clean containers and verify the packaged files.
#
# Usage: smoke-test-deb.sh <package.deb> [container-image ...]
#
# Defaults to every Debian/Ubuntu release that instantWM supports. The package
# must have been built on the oldest release in the list, otherwise the
# versioned dependencies generated by dpkg-shlibdeps can be too new.
set -euo pipefail

if [[ $# -lt 1 ]]; then
	echo "usage: $0 <package.deb> [container-image ...]" >&2
	exit 2
fi

DEB="$(realpath "$1")"
shift

if [[ $# -eq 0 ]]; then
	set -- \
		ubuntu:22.04 \
		ubuntu:24.04 \
		ubuntu:26.04 \
		ubuntu:26.10 \
		debian:12 \
		debian:13
fi

for image in "$@"; do
	echo "==> smoke testing ${DEB} on ${image}"
	docker run --rm \
		-e DEBIAN_FRONTEND=noninteractive \
		-v "${DEB}:/tmp/instantwm.deb:ro" \
		"${image}" \
		sh -ec '
			apt-get update
			apt-get install -y --no-install-recommends /tmp/instantwm.deb
			instantwm --help > /dev/null
			instantwmctl --help > /dev/null
			command -v dbus-run-session
			command -v setxkbmap
			test -x /usr/bin/startinstantos
			test -x /usr/bin/instantwm-debug
			test -f /usr/share/xsessions/instantwm.desktop
			test -f /usr/share/wayland-sessions/instantwm-wayland.desktop
			test -f /usr/share/xdg-desktop-portal/instantwm-portals.conf
			test -f /usr/lib/systemd/user/instantwm-session.target
		'
done
